<?php session_start();header('Content-Type: application/json');require 'config.php';if(!isset($_SESSION['admin_id'])){http_response_code(401);exit;} $id=(int)($_POST['id']??0);$a=$_POST['accion']??'';$s=$pdo->prepare('SELECT archivo FROM galeria WHERE id=:id');$s->execute([':id'=>$id]);$r=$s->fetch();if(!$r){http_response_code(404);echo json_encode(['message'=>'No encontrada']);exit;}if($a==='aprobar'||$a==='rechazar'){$q=$pdo->prepare('UPDATE galeria SET aprobado=:v WHERE id=:id');$q->execute([':v'=>$a==='aprobar'?1:0,':id'=>$id]);echo json_encode(['message'=>$a==='aprobar'?'Fotografía aprobada.':'Fotografía retirada.']);exit;}if($a==='eliminar'){$q=$pdo->prepare('DELETE FROM galeria WHERE id=:id');$q->execute([':id'=>$id]);$f=dirname(__DIR__).'/uploads/'.basename($r['archivo']);if(is_file($f))unlink($f);echo json_encode(['message'=>'Fotografía eliminada.']);}
